--
-- Name: partner_earnings_view; Type: VIEW; Schema: public; Owner: nev
--

CREATE VIEW public.partner_earnings_view AS
 WITH first_payments AS (
         SELECT u.id AS user_id,
            u.telegram_user_id,
            fv.partner_telegram_user_id,
            min(p_1.id) AS first_payment_id
           FROM ((public.users u
             JOIN public.first_visitors fv ON (((u.telegram_user_id = fv.telegram_user_id) AND (fv.partner_telegram_user_id IS NOT NULL))))
             JOIN public.payments p_1 ON (((p_1.user_id = u.id) AND (p_1.amount > 1.00))))
          GROUP BY u.id, u.telegram_user_id, fv.partner_telegram_user_id
        )
 SELECT fp.partner_telegram_user_id AS telegram_user_id,
    round(sum((p.amount * 0.20)), 2) AS total_earned,
    round(sum((p.amount * 0.20)), 2) AS available_balance,
    count(DISTINCT fp.user_id) AS referred_customers_count,
    max(p.created_at) AS last_referral_date,
    min(p.created_at) AS first_referral_date,
    avg((p.amount * 0.20)) AS avg_earning_per_referral
   FROM (first_payments fp
     JOIN public.payments p ON ((p.id = fp.first_payment_id)))
  GROUP BY fp.partner_telegram_user_id;


