CREATE VIEW public.user_with_configs_view AS
 SELECT u.id AS user_id,
    u.telegram_user_id,
    u.email,
    u.created_at AS user_created_at,
    p.payment_id,
    p.payment_description,
    p.number_orders_count,
    p.service_status,
    vc.wg_easy_name,
